  context.append(result)

class Thread:
  events: List[Event]

class Event:
  # could just use string, or could be explicit - up to you
  type: Literal["list_git_tags", "deploy_backend", "deploy_frontend",
                "request_more_information", "done_for_now",
                "list_git_tags_result", "deploy_backend_result",
                "deploy_frontend_result", "request_more_information_result",
                "done_for_now_result", "error"]
  data: ListGitTags | DeployBackend | DeployFrontend | RequestMoreInformation | \
        ListGitTagsResult | DeployBackendResult | DeployFrontendResult | \
        RequestMoreInformationResult | str

def event_to_prompt(event: Event) -> str:
    data = event.data if isinstance(event.data, str) \
           else stringifyToYaml(event.data)
    return f"<{event.type}>\n{data}\n</{event.type}>"

def thread_to_prompt(thread: Thread) -> str:
  return '\n\n'.join(event_to_prompt(event) for event in thread.events)

nextStep = await determine_next_step(thread_to_prompt(thread))

consecutive_errors = 0
while True:
  next_step = await determine_next_step(thread_to_prompt(thread))
  thread.events.append({"type": next_step.intent, "data": next_step})
  try:
    if next_step.intent == 'request_clarification':
      await send_message_to_human(next_step)
      await db.save_thread(thread)
      break        # async step: a webhook will resume us later
    elif next_step.intent == 'fetch_git_tags':
      tags = await fetch_git_tags()
      thread.events.append({"type": 'fetch_git_tags_result', "data": tags})
      consecutive_errors = 0
      continue     # sync step: straight back to the model
    elif next_step.intent == 'deploy_backend':
      await request_human_approval(next_step)
      await db.save_thread(thread)
      break        # high stakes: wait for approval
  except Exception as e:
    consecutive_errors += 1
    if consecutive_errors < 3:
      thread.events.append({"type": 'error', "data": format_error(e)})
    else:
      break        # escalate to a human, compact context, etc.

// the whole agent is a reducer over events: (thread) => thread
export async function agentLoop(thread: Thread): Promise<Thread> {
    while (true) {
        const nextStep = await b.DetermineNextStep(thread.serializeForLLM());
        thread.events.push({ type: "tool_call", data: nextStep });

        switch (nextStep.intent) {
            case "done_for_now":
            case "request_more_information":
                // hand the thread back to whoever called us
                return thread;
            case "add":
            case "subtract":
            case "multiply":
            case "divide":
                thread = await handleNextStep(nextStep, thread);
        }
    }
}

export class Thread {
    events: Event[] = [];

    serializeForLLM() {
        return this.events.map(e => this.serializeOneEvent(e)).join("\n");
    }

    serializeOneEvent(e: Event) {
        const tag = e.data?.intent || e.type;
        const body = typeof e.data !== 'object' ? e.data :
            Object.keys(e.data).filter(k => k !== 'intent')
                .map(k => `${k}: ${e.data[k]}`).join("\n");
        return `<${tag}>\n${body}\n</${tag}>`;
    }

    awaitingHumanResponse(): boolean {
        const last = this.events[this.events.length - 1];
        return ['request_more_information', 'done_for_now'].includes(last.data.intent);
    }

    awaitingHumanApproval(): boolean {
        const last = this.events[this.events.length - 1];
        return last.data.intent === 'divide';
    }
}
